// This script is injected into each tab.
import browser from "webextension-polyfill";
import Relay from "../../Relay";
import {
  REQUEST_TAB_ID,
  CREATE_DEVTOOLS_PANEL,
  EXPLORER_RESPONSE,
  RELOADING_TAB,
  RELOAD_TAB_COMPLETE,
} from "../constants";
import type { RPCMessage } from "../messages";
import type { MessageAdapter } from "../messageAdapters";
import {
  createPortMessageAdapter,
  createWindowMessageAdapter,
} from "../messageAdapters";
import { createRPCBridge } from "../rpc";

// Inspected tabs are unable to retrieve their own ids.
// This requests the tab's id from the background script.
// Once it resolves, we can create the tab's Relay.
async function requestId() {
  return browser.runtime.sendMessage({ message: REQUEST_TAB_ID });
}

async function setup() {
  const id = await requestId();
  const tab = new Relay();
  const port = browser.runtime.connect({
    name: `tab-${id}`,
  });

  tab.addConnection("background", (message) => {
    port.postMessage(message);
  });

  port.onMessage.addListener(tab.broadcast);

  window.addEventListener("message", (event) => {
    tab.broadcast(event?.data);
  });

  tab.addConnection("client", (message) => {
    window.postMessage(message, "*");
  });

  const devtools = `background:devtools-${id}`;
  tab.forward(CREATE_DEVTOOLS_PANEL, devtools);
  tab.forward(RELOADING_TAB, devtools);
  tab.forward(RELOAD_TAB_COMPLETE, devtools);
  tab.forward(EXPLORER_RESPONSE, `${devtools}:explorer`);

  // RPC messages are routed directly between the devtools port and the
  // inspected page, bypassing the Relay's event-based forwarding. The
  // destination of messages forwarded to the port is set so that the
  // background script can route them back to the devtools script.
  const rpcPortAdapter: MessageAdapter<RPCMessage> = {
    ...createPortMessageAdapter(port),
    postMessage: (message) =>
      port.postMessage({ ...message, to: `devtools-${id}` }),
  };
  createRPCBridge(rpcPortAdapter, createWindowMessageAdapter(window));
}

setup();

