export interface ProductDimension {
  size: string;
  weight: number;
}

export interface ProductVariation {
  id: string;
  name: string;
}

export interface Product {
  id: string;
  title: string;
  description: string;
  dimensions?: ProductDimension;
  variation?: ProductVariation;
}

export interface GetProductsQuery {
  products: Product[];
}

import { gql } from 'apollo-angular';

export const GET_PRODUCTS = gql`
  query GetProducts {
    products {
      id
      title
      description
      ...ProductDetails @defer
    }
  }

  fragment ProductDetails on Product {
    dimensions {
      size
      weight
    }
    variation {
      id
      name
    }
  }
`;

import { Component, DestroyRef, OnInit, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { Apollo, WatchQueryOptions } from 'apollo-angular';
import { Observable, map, tap } from 'rxjs';

import { GET_PRODUCTS } from '../product.query';
import { GetProductsQuery, Product } from '../types';

@Component({
  selector: 'app-product-list',
  templateUrl: './product-list.component.html',
  styleUrls: ['./product-list.component.css'],
})
export class ProductListComponent implements OnInit {
  private readonly apollo = inject(Apollo);

  products$: Observable<Product[]>;
  loading = true;
  error: string | null = null;

  ngOnInit(): void {
    const watchQuery = this.apollo.watchQuery<GetProductsQuery>({
      query: GET_PRODUCTS,
    });

    this.products$ = watchQuery.valueChanges.pipe(
      takeUntilDestroyed(inject(DestroyRef)),
      tap(({ loading, errors }) => {
        this.loading = loading;
        this.error =
          errors && errors.length > 0 ? errors.map((err) => err.message).join(', ') : null;
      }),
      map(({ data }) => data.products ?? []),
    );
  }

  isDeferred(product: Product): boolean {
    return !!(product.dimensions || product.variation);
  }
}

