import { deserializeError, serializeError } from "../errorSerialization";

test("serializes an error to its name, message, and stack", () => {
  const error = new Error("Something went wrong");

  expect(serializeError(error)).toEqual({
    name: "Error",
    message: "Something went wrong",
    stack: expect.any(String),
  });
});

test("does not serialize non-error values as errors", () => {
  expect(serializeError("Something went wrong")).toEqual({
    message: "Something went wrong",
  });
});

test("deserializes a serialized error", () => {
  const error = new Error("Something went wrong");

  expect(deserializeError(serializeError(error))).toEqual(
    new Error("Something went wrong")
  );
});

test("deserializes the correct error class by name", () => {
  const serialized = {
    name: "TypeError",
    message: "Not a function",
    stack: "TypeError: Not a function",
  };

  const error = deserializeError(serialized);

  expect(error).toBeInstanceOf(TypeError);
  expect(error.name).toBe("TypeError");
  expect(error.message).toBe("Not a function");
  expect(error.stack).toBe("TypeError: Not a function");
});

test("preserves an error through a JSON round trip", () => {
  const received = JSON.parse(JSON.stringify(serializeError(new Error("Nope"))));

  const error = deserializeError(received);

  expect(error).toEqual(new Error("Nope"));
  expect(error).toBeInstanceOf(Error);
});

