# Generates all-clients/package.json with a dependency entry for every stable
# version of @apollo/client at or above the minimum supported version. This
# filter is fed the full npm registry packument for @apollo/client:
#
#   curl -s https://registry.npmjs.org/@apollo/client | jq -f package.jq

def is_stable:
  test("^[0-9]+\\.[0-9]+\\.[0-9]+$");

def version_key:
  split(".") | map(tonumber) | { major: .[0], minor: .[1], patch: .[2] };

def is_supported:
  version_key as $version
  | ($version.major > 3)
    or ($version.major == 3 and $version.minor >= 8);

{
  "name": "all-clients",
  "description": "A monorepo package that includes all versions of @apollo/client for which we generate full error messages.",
  "version": "0.0.0",
  "private": true,
  "scripts": {
    "rebuild": "curl -s https://registry.npmjs.org/@apollo/client | jq -f package.jq | tee package.json",
    "encode": "node encode-errorcodes.mjs"
  },
  "devDependencies": {
    "semver": "^7.5.4"
  },
  "dependencies":
    [ .versions | keys[] | select(is_stable) | select(is_supported) ]
    | sort_by(split(".") | map(tonumber))
    | map({ ("@apollo-client/" + .) : ("npm:@apollo/client@" + .) })
    | add
}

