import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath, pathToFileURL } from "node:url";
import semver from "semver";

const require = createRequire(import.meta.url);
const __dirname = path.dirname(fileURLToPath(import.meta.url));

const packageJson = JSON.parse(
  fs.readFileSync(path.join(__dirname, "package.json"), "utf-8")
);

const versions = Object.keys(packageJson.dependencies)
  .filter((name) => name.startsWith("@apollo-client/"))
  .map((name) => name.slice("@apollo-client/".length))
  .filter((version) => semver.valid(version))
  .sort(semver.compare);

// The error codes are split across several exported categories. The full set
// is needed so both `loadErrorMessages` (invariant errors) and
// `loadDevMessages` (console messages) can be resolved.
const categories = ["errorCodes", "devDebug", "devLog", "devWarn", "devError"];

async function importInvariantErrorCodes(version) {
  const packageDirectory = path.dirname(
    require.resolve(`@apollo-client/${version}/package.json`)
  );
  const module = await import(
    pathToFileURL(path.join(packageDirectory, "invariantErrorCodes.js")).href
  );
  return module;
}

// Massages the exported categories into a compact, deterministic structure
// containing only the entries needed to resolve full error messages.
function encodeCategories(module) {
  const payload = {};
  for (const category of categories) {
    const entries = module[category];
    if (!entries) {
      continue;
    }
    const messages = {};
    for (const [code, definition] of Object.entries(entries)) {
      if (definition?.message) {
        messages[code] = definition.message;
      }
    }
    if (Object.keys(messages).length > 0) {
      payload[category] = messages;
    }
  }
  return payload;
}

// Many patch releases share identical error codes. Versions are grouped by
// their encoded payload so the resulting file stays small and every version
// only needs to be stored once.
const groups = new Map();

for (const version of versions) {
  const module = await importInvariantErrorCodes(version);
  const payload = encodeCategories(module);
  const serialized = JSON.stringify(payload);
  const group = groups.get(serialized) ?? [];
  group.push(version);
  groups.set(serialized, group);
}

const errorCodes = {};

for (const [serialized, groupedVersions] of groups) {
  groupedVersions.sort(semver.compare);
  errorCodes[groupedVersions.join("|")] = Buffer.from(serialized).toString(
    "base64"
  );
}

fs.writeFileSync(
  path.join(__dirname, "errorcodes.json"),
  JSON.stringify(errorCodes)
);

