// Decodes the base64 encoded error codes stored in errorcodes.json back into
// readable objects that can be injected into the global error message handler.
//
// errorcodes.json groups versions with identical error codes under a single
// pipe-separated key so the payload is only stored once:
//
//   { "3.8.0|3.8.1": "<base64>", "3.8.2": "<base64>" }
//
// This expands each group back into a version-keyed map:
//
//   { "3.8.0": { errorCodes: {...} }, "3.8.1": { errorCodes: {...} }, ... }
export function restoreErrorCodes(encodedErrorCodes) {
  const errorCodes = {};
  for (const [versions, encoded] of Object.entries(encodedErrorCodes)) {
    const decoded = decodeErrorCodes(encoded);
    for (const version of versions.split("|")) {
      errorCodes[version] = decoded;
    }
  }
  return errorCodes;
}

function decodeErrorCodes(encoded) {
  const binary = atob(encoded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return JSON.parse(new TextDecoder().decode(bytes));
}

