export async function loadErrorCodes(
  rpcClient: RpcClient<ErrorCodesHandler>,
  version: string
) {
  const categories = await rpcClient.request("getErrorCodes", version);
  if (!categories) {
    return;
  }
  loadErrorMessageHandler(version, categories);
