  version: string,
  categories: ErrorCodeCategories
) {
  const handlerSymbol = Symbol.for(`ApolloErrorMessageHandler_${version}`);
  const globalObject: Record<PropertyKey, unknown> = globalThis;
  const existing = globalObject[handlerSymbol];
  const handler =
    typeof existing === "function" ? existing : createErrorMessageHandler();
