import type { RpcClient } from "../rpc";

export type ErrorCodeCategories = Partial<{
  errorCodes: Record<string, string>;
  devDebug: Record<string, string>;
  devLog: Record<string, string>;
  devWarn: Record<string, string>;
  devError: Record<string, string>;
}>;

export type ErrorCodesHandler = {
  getErrorCodes: (version: string) => Promise<ErrorCodeCategories | undefined>;
};

type ErrorMessageHandlerWithCodes = {
  (message: unknown, args: unknown[]): unknown;
  [code: string]: unknown;
};

declare global {
  interface Window {
    [key: symbol]: unknown;
  }
}

export async function loadErrorCodes(
  rpcClient: RpcClient<ErrorCodesHandler>,
  version: string
) {
  const categories = await rpcClient.request("getErrorCodes", version);
  if (!categories) {
    return;
  }

  const handlerSymbol = Symbol.for(`ApolloErrorMessageHandler_${version}`);
  const globalObject = globalThis as Record<PropertyKey, unknown>;
  let handler = globalObject[handlerSymbol] as ErrorMessageHandlerWithCodes;

  if (typeof handler !== "function") {
    handler = createErrorMessageHandler();
    globalObject[handlerSymbol] = handler;
  }

  for (const category of Object.values(categories)) {
    for (const [code, message] of Object.entries(category ?? {})) {
      // Avoid overwriting codes that are already loaded for this version.
      if (typeof handler[code] === "undefined") {
        handler[code] = message;
      }
    }
  }
}

function createErrorMessageHandler(): ErrorMessageHandlerWithCodes {
  const handler = ((message, args) => {
    if (typeof message === "number") {
      const fullMessage = handler[String(message)];
      if (!message || typeof fullMessage !== "string") {
        return undefined;
      }
      message = fullMessage;
    }
    return args.reduce(
      (msg, arg) => msg.replace(/%[sdfo]/, String(arg)),
      String(message)
    );
  }) as ErrorMessageHandlerWithCodes;
  return handler;
}

export type ErrorCode = Record<string, string>;

export type ErrorCodeCategories = Partial<{
  errorCodes: ErrorCode;
  devDebug: ErrorCode;
  devLog: ErrorCode;
  devWarn: ErrorCode;
  devError: ErrorCode;
}>;

export type EncodedErrorCodes = Record<string, string>;

export declare function restoreErrorCodes(
  encodedErrorCodes: EncodedErrorCodes
): Record<string, ErrorCodeCategories>;

